# owner: platform
import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.parsing import parse_span
from hourglass.models import Span


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(60, 120)], step)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 30, 60):
            self.assertEqual(len(rounded_labels([Span(0, 120)], step)), 1)

    def test_non_integer_step_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(60, 120)], 7.5)


class RoundingTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        self.assertEqual(round_span(Span(543, 1027), 15), Span(540, 1020))

    def test_halves_round_up(self):
        self.assertEqual(round_span(Span(67, 128), 15), Span(60, 135))

    def test_end_of_day_stays(self):
        self.assertEqual(round_span(Span(60, 1440), 30), Span(60, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 64), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [parse_span("09:02-17:14")]
        self.assertEqual(
            rounded_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_one_label_per_span(self):
        spans = [parse_span("08:00-12:00"), parse_span("13:00-13:40")]
        self.assertEqual(
            rounded_labels(spans, 30),
            ["08:00-12:00 (4h 0m)", "13:00-13:30 (0h 30m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])
